"""Decide how much of an expense each person owes."""

from tabtally.errors import MoneyError
from tabtally.money import allocate


def split_equally(cents: int, people: list[str]) -> dict[str, int]:
    _ensure_unique(people)
    return dict(zip(people, allocate(cents, [1] * len(people))))


def split_by_percent(cents: int, shares: list[tuple[str, int]]) -> dict[str, int]:
    """Split cents by whole-number percentages, which must add up to 100."""
    names = [name for name, _ in shares]
    _ensure_unique(names)
    total = sum(percent for _, percent in shares)
    if total != 100:
        raise MoneyError(f"percentages must add up to 100, not {total}")
    return dict(zip(names, allocate(cents, [percent for _, percent in shares])))


def _ensure_unique(names: list[str]) -> None:
    duplicates = sorted({name for name in names if names.count(name) > 1})
    if duplicates:
        raise MoneyError(f"listed more than once: {', '.join(duplicates)}")

